typedef unsigned int u_int;

class game
{
  char data[552];
  int beach_id;
public:
  int get_beach_id() const { return beach_id; }
};

struct BeachData
{
  char data[208];
  int bdir;
  char tail[320];
};

extern game* g_game_ptr;
extern BeachData BeachDataArray[];
extern bool WAVE_LeftBreaker;
extern u_int WAVE_MeshNumVert;
extern u_int WaveMeshID;
extern float WAVE_TexMinU;
extern float WAVE_TexMaxU;
extern float WAVE_TexMinV;
extern float WAVE_TexMaxV;

enum { WAVETEX_MATWAVE = 0 };
#define WAVE_TILELIMIT 2048

bool WAVETEX_LoadTextureAnims(bool resetparms=true);
void WAVETEX_Init(void);
u_int WAVETEX_InitWaveMesh(u_int nvert, int mattype, void (*fillinfunc)(void) = 0);
u_int WAVETEX_Width(int textype=0, int frame=-1);
u_int WAVETEX_Height(int textype=0, int frame=-1);
void WAVE_FillInMesh(void);
void WAVE_LoadAll(void);
void WAVE_Reset(void);

void WAVE_Init(void)
{
	#ifdef TARGET_GC
		int index=0;
		#undef USEINFO
		#ifdef DEBUG
			#define USEINFO(xx, zz, nn, cc) WAVE_Marker[index].x=xx;    \
			                                   WAVE_Marker[index].z=zz;    \
			                                   strcpy(WAVE_Marker[index].name, #nn ); \
			                                   WAVE_Marker[index].color=COLOR_##cc;    \
			                                   index++;
		#else
			#define USEINFO(xx, zz, nn, cc) WAVE_Marker[index].x=xx;    \
			                                   WAVE_Marker[index].z=zz;    \
			                                   index++;
		#endif
		#include "wavemarker.txt"

	#endif



#if defined(TARGET_PS2)
	assert(!( ((u_int) (WAVE_ControlPoints)) & (16 - 1) ));	// verify alignment
#endif

	int curbeach=g_game_ptr->get_beach_id();

	WAVE_LeftBreaker = BeachDataArray[curbeach].bdir;

	WAVETEX_LoadTextureAnims();
	WAVETEX_Init();
#ifdef TARGET_XBOX
	WAVERENDER_Init();
#endif
	WaveMeshID = WAVETEX_InitWaveMesh(WAVE_MeshNumVert, WAVETEX_MATWAVE, WAVE_FillInMesh);

	WAVE_TexMinU = - WAVE_TILELIMIT / (int) WAVETEX_Width();	// signed type
	WAVE_TexMaxU = WAVE_TILELIMIT / WAVETEX_Width();

	WAVE_TexMinV = - WAVE_TILELIMIT / (int) WAVETEX_Height();
	WAVE_TexMaxV = WAVE_TILELIMIT / WAVETEX_Height();

	WAVE_LoadAll();
	WAVE_Reset();
}
